import {uploadFile} from './upload.js';

export function createCreativeLibraryUI({api,getState,esc,refresh,toast}){
 let picker=null,pending=0;
 const drafts=new Map();
 const owner=()=>getState()?.company?.id;
 const busy=()=>pending>0||!!picker?.isConnected;
 const draftKey=key=>owner()+':'+key;
 const draft=(key,fallback)=>drafts.has(draftKey(key))?drafts.get(draftKey(key)):fallback;
 const showStatus=(input,message)=>{const group=input.closest('details');let status=group?.querySelector('[data-library-status]');if(group&&!status){status=document.createElement('p');status.dataset.libraryStatus='';status.setAttribute('role','status');group.querySelector('summary').after(status);}if(status)status.textContent=message;};
 const roles={reference:'Referência e inspiração',material:'Material para criar',brand:'Identidade oficial'};
 const assetCard=(a,entry={})=>`<article class="creative-file"><a href="${esc(a.url)}" target="_blank" rel="noopener">${a.mime.startsWith('image/')?`<img loading="lazy" src="${esc(a.url)}" alt="${esc(a.name)}">`:`<span class="creative-file-type">${a.mime==='video/mp4'?'Vídeo':a.mime.startsWith('audio/')?'Áudio':'Documento'}</span>`}<strong>${esc(a.name)}</strong></a><label>Usar como<select data-library-role="${esc(a.id)}">${Object.entries(roles).map(([v,l])=>`<option value="${v}" ${v===draft(a.id+':role',entry.role||'material')?'selected':''}>${l}</option>`).join('')}</select></label><label>O que aproveitar desta referência?<textarea data-library-notes="${esc(a.id)}" maxlength="2000" rows="2" placeholder="Ex.: hierarquia, fonte, cores, cortes…">${esc(draft(a.id+':notes',entry.notes||''))}</textarea></label><button class="p-button secondary" data-library-save="${esc(a.id)}">Salvar organização</button></article>`;
 function group(role,title,description,assets,entries){return `<details class="creative-library-group"><summary><strong>${title}</strong><span>${assets.length} arquivo(s)</span></summary><p>${description}</p><label class="p-button secondary">Adicionar arquivo<input type="file" data-library-upload="${role}" accept="${role==='reference'?'image/png,image/jpeg,image/webp,video/mp4':'image/png,image/jpeg,image/webp,video/mp4,audio/mpeg,audio/wav,audio/ogg,application/pdf'}" hidden></label><div class="creative-library-grid">${assets.map(a=>assetCard(a,entries.find(e=>e.assetId===a.id))).join('')||'<p>Nenhum arquivo neste grupo.</p>'}</div></details>`;}
 function render(contents){const s=getState(),lib=s.creativeLibrary||{},entries=lib.entries||[],generated=new Set((s.records.content||[]).map(c=>c.assetId).filter(Boolean)),official=new Set([s.brandMaterials?.logoAssetId,s.brandMaterials?.fontAssetId].filter(Boolean));
  const files=(s.assets||[]).filter(a=>!generated.has(a.id)),role=a=>official.has(a.id)?'brand':entries.find(e=>e.assetId===a.id)?.role||'material';
  return `<section class="creative-library"><p class="micro-copy">Sua identidade fica em <a href="#/brand">Minha empresa → Marca</a>. Referências orientam o estilo; materiais entram na criação. Abra um grupo para consultar.</p><details class="creative-library-group"><summary><strong>Direção para próximas criações</strong><span>${lib.defined?'Definida':'A definir'}</span></summary><p>Descreva o que gosta e o que deseja evitar. Isso orienta imagens e vídeos desta empresa.</p><textarea id="creative-direction" maxlength="4000" rows="4" placeholder="Ex.: visual clean, fotos em destaque, títulos curtos e evitar excesso de elementos.">${esc(draft('direction',lib.direction||''))}</textarea><button class="p-button secondary" data-library-direction>Salvar orientação</button></details>
  ${group('reference','Referências e inspirações','Prints e exemplos de estilo. A marca e o produto da referência não são copiados para sua peça.',files.filter(a=>role(a)==='reference'),entries)}
  ${group('material','Materiais para criar','Fotos, vídeos, áudios e documentos da empresa que podem entrar nas produções.',files.filter(a=>role(a)==='material'),entries)}
  <details class="creative-library-group"><summary><strong>Estilos aprovados</strong><span>${(lib.styles||[]).length} estilo(s)</span></summary><p>Aprovar uma entrega não altera o estilo permanente. Use “Salvar como estilo” em uma prévia aprovada.</p><div class="creative-library-grid">${(lib.styles||[]).map(style=>{const a=s.assets.find(a=>a.id===style.assetIds?.[0]);return `<article class="creative-file">${a?.mime.startsWith('image/')?`<img loading="lazy" src="${esc(a.url)}" alt="${esc(style.name)}">`:''}<h3>${esc(style.name)}</h3><p>${style.format==='reels'?'Vídeo':'Imagem'} · referência para próximas criações</p><a href="#/create/${style.format==='reels'?'reels':'feed'}">Criar conteúdo</a></article>`;}).join('')||'<p>Nenhum estilo salvo ainda.</p>'}</div></details>
  <details class="creative-library-group"><summary><strong>Minhas criações</strong><span>${(s.records.content||[]).length} conteúdo(s)</span></summary><a class="p-button secondary" href="#/create">Revisar prévias, pedir ajustes e salvar estilos</a>${contents}</details>
  <details class="creative-library-group"><summary><strong>Identidade oficial</strong><span>${files.filter(a=>role(a)==='brand').length} arquivo(s)</span></summary><p>Logo, cores e fontes são configurados em <a href="#/brand">Minha empresa → Marca</a>. Classificar um arquivo aqui não substitui a configuração oficial.</p><div class="creative-library-grid">${files.filter(a=>role(a)==='brand').map(a=>assetCard(a,{...entries.find(e=>e.assetId===a.id),role:'brand'})).join('')}</div></details></section>`;
 }
 async function click(e){const b=e.target.closest('[data-library-save],[data-library-direction]');if(!b)return;const org=owner(),base='/api/portal/'+org+'/';b.disabled=true;pending++;try{if(b.hasAttribute('data-library-direction'))await api(base+'creative-library','POST',{action:'direction',direction:document.getElementById('creative-direction').value});else{const card=b.closest('article');await api(base+'creative-library','POST',{action:'classify',assetId:b.dataset.librarySave,role:card.querySelector('select').value,notes:card.querySelector('textarea').value});}for(const key of b.hasAttribute('data-library-direction')?['direction']:[b.dataset.librarySave+':notes',b.dataset.librarySave+':role'])drafts.delete(org+':'+key);if(owner()===org){pending--;try{await refresh();toast('Preferência salva nesta empresa.');}finally{pending++;}}}catch(error){toast(error.message,true);}finally{pending--;b.disabled=false;}}
 async function change(e){const input=e.target;if(!input.matches('[data-library-upload]'))return;picker=null;const file=input.files?.[0];if(!file)return;const org=owner(),role=input.dataset.libraryUpload,base='/api/portal/'+org+'/';input.disabled=true;pending++;let uploaded=false;showStatus(input,'Enviando arquivo…');try{const a=await uploadFile(base+'files',file);uploaded=true;showStatus(input,'Organizando na biblioteca…');await api(base+'creative-library','POST',{action:'classify',assetId:a.id,role});if(owner()===org){pending--;try{await refresh();toast('Arquivo salvo no grupo escolhido.');}finally{pending++;}}}catch(error){const message=uploaded?'O arquivo foi enviado, mas não foi organizado. Procure-o em Materiais para criar e selecione Referência e inspiração. '+error.message:error.message;showStatus(input,message);toast(message,true);}finally{pending--;input.disabled=false;input.value='';}}
 document.addEventListener('click',e=>{if(e.target.matches('[data-library-upload]'))picker=e.target;});
 document.addEventListener('cancel',e=>{if(e.target===picker)picker=null;},true);
 document.addEventListener('input',e=>{const el=e.target;if(el.id==='creative-direction')drafts.set(draftKey('direction'),el.value);else if(el.matches('[data-library-notes],[data-library-role]'))drafts.set(draftKey((el.dataset.libraryNotes||el.dataset.libraryRole)+(el.hasAttribute('data-library-notes')?':notes':':role')),el.value);});
 document.addEventListener('click',click);document.addEventListener('change',change);
 return {render,get busy(){return busy();}};
}
